<?php require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';if(isset($_GET['read'])){$pdo->prepare('UPDATE notifications SET read_at=NOW() WHERE id=? AND (user_id=? OR user_id IS NULL)')->execute([(int)$_GET['read'],user()['id']]);redirect('notifications.php');}if(isset($_GET['all'])){$pdo->prepare('UPDATE notifications SET read_at=NOW() WHERE user_id=? OR user_id IS NULL')->execute([user()['id']]);redirect('notifications.php');}$rows=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? OR user_id IS NULL ORDER BY id DESC LIMIT 100');$rows->execute([user()['id']]);$rows=$rows->fetchAll();render_header('Notifications','notifications');page_title('Notifications','ALERT CENTER','Low stock, approvals, system events and operational alerts.','Mark All Read',app_url('notifications.php?all=1'));?><article class="card"><div class="activity-list"><?php foreach($rows as $r):?><a class="activity" href="?read=<?=$r['id']?>"><span class="activity-icon"><i data-icon="bell"></i></span><div><b><?=e($r['title'])?></b><small><?=e($r['message'])?> · <?=date('d M Y H:i',strtotime($r['created_at']))?></small></div><?php if(!$r['read_at']):?><span class="status pending">NEW</span><?php endif;?></a><?php endforeach;?><?php if(!$rows):?><div class="empty"><div class="empty-icon"><i data-icon="bell"></i></div>You are all caught up.</div><?php endif;?></div></article><?php render_footer('notifications');
